corrected_code:
package dashboard

import (
	"context"
	"gorm.io/gorm"
	"myapp/auth"
	"myapp/models"
)

type WidgetRepository struct {
	DB *gorm.DB
}

func (r *WidgetRepository) GetWidgetConfig(ctx context.Context, widgetID string) (*models.DashboardWidget, error) {
	var widget models.DashboardWidget
	workspaceID := auth.GetWorkspaceID(ctx)

	if err := r.DB.WithContext(ctx).
		Where("widget_id = ? AND workspace_id = ?", widgetID, workspaceID).
		First(&widget).Error; err != nil {
		return nil, err
	}

	return &widget, nil
}
